<div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3 mb-0">满意度报表</h1><a class="btn btn-outline-secondary" href="<?= h(url_to('admin/ticket/index')) ?>">返回工单</a></div>
<form class="card card-body mb-3" method="get" action="<?= h(url_to('admin/satisfaction/index')) ?>"><div class="row g-2 align-items-end"><div class="col-md-3"><label class="form-label">开始日期</label><input class="form-control" type="date" name="from" value="<?= h($from) ?>"></div><div class="col-md-3"><label class="form-label">结束日期</label><input class="form-control" type="date" name="to" value="<?= h($to) ?>"></div><div class="col-md-3"><label class="form-label">部门</label><input class="form-control" name="department" value="<?= h($department) ?>"></div><div class="col-md-3"><button class="btn btn-primary">筛选</button></div></div></form>
<div class="row g-3 mb-3"><div class="col-md-3"><div class="card card-body"><div class="text-muted">评价数</div><strong><?= (int)$report['summary']['count'] ?></strong></div></div><div class="col-md-3"><div class="card card-body"><div class="text-muted">平均分</div><strong><?= h($report['summary']['avg']) ?></strong></div></div><div class="col-md-6"><div class="card card-body"><div class="text-muted mb-1">各分数</div><?php foreach ($report['summary']['levels'] as $score => $count): ?><span class="badge text-bg-light me-1"><?= (int)$score ?> 分：<?= (int)$count ?></span><?php endforeach; ?></div></div></div>
<div class="card mb-3"><div class="card-header">按客服/处理人</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>管理员 ID</th><th>评价数</th><th>平均分</th><th>各分数</th></tr></thead><tbody><?php foreach ($report['staff'] as $x): ?><tr><td><?= (int)$x['admin_id'] ?: '未分配' ?></td><td><?= (int)$x['count'] ?></td><td><?= h($x['avg']) ?></td><td><?php foreach ($x['levels'] as $s => $n): if ($n): ?><span class="badge text-bg-light me-1"><?= (int)$s ?>:<?= (int)$n ?></span><?php endif; endforeach; ?></td></tr><?php endforeach; ?><?php if (!$report['staff']): ?><tr><td colspan="4" class="empty">暂无数据</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card mb-3"><div class="card-header">按部门</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>部门</th><th>评价数</th><th>平均分</th></tr></thead><tbody><?php foreach ($report['departments'] as $name => $x): ?><tr><td><?= h($name) ?></td><td><?= (int)$x['count'] ?></td><td><?= h($x['avg']) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="card"><div class="card-header text-danger">差评（≤2 分）</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>工单</th><th>分数</th><th>评价</th><th>时间</th></tr></thead><tbody><?php foreach ($bad as $r): ?><tr><td><a href="<?= h(url_to('admin/ticket/detail', array('id' => $r['ticket_id']))) ?>">#<?= (int)$r['ticket_id'] ?> <?= h($r['subject']) ?></a></td><td class="text-danger"><?= (int)$r['score'] ?></td><td><?= h($r['comment']) ?></td><td><?= h(fmt_time($r['create_time'])) ?></td></tr><?php endforeach; ?><?php if (!$bad): ?><tr><td colspan="4" class="empty">暂无差评</td></tr><?php endif; ?></tbody></table></div></div>
